import React, { useState, useEffect } from 'react';
import { useQuiz } from '../context/QuizContext';
import { generateFeedbackWithAI } from '../services/openaiService';
import AnswerReview from './AnswerReview';

const QuizScreen = () => {
  const { state, actions } = useQuiz();
  const [showResults, setShowResults] = useState(false);
  const [selectedAnswer, setSelectedAnswer] = useState(null);
  const [showAnswerFeedback, setShowAnswerFeedback] = useState(false);
  const [answerSubmitted, setAnswerSubmitted] = useState(false);
  const [showAnswerReview, setShowAnswerReview] = useState(false);

  const currentQuestion = state.questions[state.currentQuestionIndex];
  const totalQuestions = state.questions.length;
  const progress = ((state.currentQuestionIndex + 1) / totalQuestions) * 100;

  useEffect(() => {
    // Set the selected answer for the current question
    setSelectedAnswer(state.answers[state.currentQuestionIndex]);
    setShowAnswerFeedback(false);
    setAnswerSubmitted(false);
  }, [state.currentQuestionIndex, state.answers]);

  const handleAnswerSelect = (answerIndex) => {
    if (answerSubmitted) return; // Prevent changing answer after submission
    
    setSelectedAnswer(answerIndex);
    actions.setAnswer(answerIndex);
  };

  const handleSubmitAnswer = () => {
    if (selectedAnswer === null) return;
    
    setAnswerSubmitted(true);
    setShowAnswerFeedback(true);
  };

  const handleNext = () => {
    if (state.currentQuestionIndex < totalQuestions - 1) {
      actions.nextQuestion();
    } else {
      // Show answer review before finishing
      setShowAnswerReview(true);
    }
  };

  const handleReviewContinue = () => {
    setShowAnswerReview(false);
    calculateScoreAndFeedback();
  };

  const handleReviewGoBack = () => {
    setShowAnswerReview(false);
    // Go back to first question
    actions.setCurrentQuestion(0);
  };

  const handlePrevious = () => {
    actions.previousQuestion();
  };

  const calculateScoreAndFeedback = async () => {
    try {
      actions.setLoading(true);
      
      // Calculate score
      let score = 0;
      state.questions.forEach((question, index) => {
        if (state.answers[index] === question.correctAnswer) {
          score++;
        }
      });
      
      actions.setScore(score);
      
      // Generate feedback
      const feedbackResult = await generateFeedbackWithAI(score, totalQuestions, state.selectedTopic, state.answers, state.questions);
      
      if (feedbackResult.success) {
        actions.setFeedback(feedbackResult.feedback);
      } else {
        actions.setError('Failed to generate feedback');
      }
    } catch (error) {
      actions.setError(error.message);
    }
  };

  const isLastQuestion = state.currentQuestionIndex === totalQuestions - 1;
  const canSubmit = selectedAnswer !== null && !answerSubmitted;
  const canGoNext = answerSubmitted;
  const isCorrect = selectedAnswer === currentQuestion.correctAnswer;

  return (
    <div className="card">
      <div className="progress-text">
        Question {state.currentQuestionIndex + 1} of {totalQuestions}
      </div>
      <div className="progress-bar">
        <div 
          className="progress-fill" 
          style={{ width: `${progress}%` }}
        ></div>
      </div>

      <div className="question-container">
        <h2 className="question-title">
          {currentQuestion.question}
        </h2>

        <div className="options-container">
          {currentQuestion.options.map((option, index) => {
            let buttonClass = 'option-button';
            
            if (answerSubmitted) {
              if (index === currentQuestion.correctAnswer) {
                buttonClass += ' correct';
              } else if (index === selectedAnswer && !isCorrect) {
                buttonClass += ' incorrect';
              }
            } else if (selectedAnswer === index) {
              buttonClass += ' selected';
            }
            
            return (
              <button
                key={index}
                className={buttonClass}
                onClick={() => handleAnswerSelect(index)}
                disabled={answerSubmitted}
              >
                <span style={{ marginRight: '10px', fontWeight: 'bold' }}>
                  {String.fromCharCode(65 + index)}.
                </span>
                {option}
                {answerSubmitted && index === currentQuestion.correctAnswer && (
                  <span style={{ marginLeft: '10px', fontSize: '1.2rem' }}>✓</span>
                )}
                {answerSubmitted && index === selectedAnswer && !isCorrect && (
                  <span style={{ marginLeft: '10px', fontSize: '1.2rem' }}>✗</span>
                )}
              </button>
            );
          })}
        </div>
      </div>

      {/* Answer Feedback Section */}
      {showAnswerFeedback && (
        <div style={{
          marginBottom: '20px',
          padding: '20px',
          borderRadius: '12px',
          background: isCorrect ? '#f0fff4' : '#fef5e7',
          border: `2px solid ${isCorrect ? '#48bb78' : '#ed8936'}`,
          animation: 'slideUp 0.3s ease-out'
        }}>
          <div style={{
            display: 'flex',
            alignItems: 'center',
            marginBottom: '10px'
          }}>
            <span style={{
              fontSize: '1.5rem',
              marginRight: '10px'
            }}>
              {isCorrect ? '🎉' : '💡'}
            </span>
            <h3 style={{
              margin: 0,
              color: isCorrect ? '#2f855a' : '#c05621',
              fontSize: '1.2rem'
            }}>
              {isCorrect ? 'Correct!' : 'Not quite right'}
            </h3>
          </div>
          <p style={{
            margin: 0,
            color: '#4a5568',
            lineHeight: '1.5'
          }}>
            {currentQuestion.explanation}
          </p>
          {!isCorrect && (
            <div style={{
              marginTop: '10px',
              padding: '10px',
              background: '#fff5f5',
              borderRadius: '8px',
              border: '1px solid #fed7d7'
            }}>
              <strong style={{ color: '#c53030' }}>Correct Answer:</strong>
              <span style={{ marginLeft: '8px', color: '#4a5568' }}>
                {String.fromCharCode(65 + currentQuestion.correctAnswer)}. {currentQuestion.options[currentQuestion.correctAnswer]}
              </span>
            </div>
          )}
        </div>
      )}

      <div className="navigation">
        <button
          className="nav-button"
          onClick={handlePrevious}
          disabled={state.currentQuestionIndex === 0}
        >
          Previous
        </button>
        
        {!answerSubmitted ? (
          <button
            className="nav-button"
            onClick={handleSubmitAnswer}
            disabled={!canSubmit}
            style={{
              background: canSubmit ? '#48bb78' : '#cbd5e0',
              color: 'white'
            }}
          >
            Submit Answer
          </button>
        ) : (
          <button
            className="nav-button"
            onClick={handleNext}
            disabled={!canGoNext}
          >
            {isLastQuestion ? 'Finish Quiz' : 'Next Question'}
          </button>
        )}
      </div>
    </div>
  );
};

export default QuizScreen;
